package com.example.incidentapp.worker;
import android.content.Context; import androidx.work.*; import java.util.concurrent.TimeUnit;
public final class SyncScheduler{private SyncScheduler(){} public static void programar(Context c){Constraints net=new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build();PeriodicWorkRequest p=new PeriodicWorkRequest.Builder(SincronizarPendientesWorker.class,15,TimeUnit.MINUTES).setConstraints(net).build();WorkManager.getInstance(c).enqueueUniquePeriodicWork("sync_incidentes_pendientes",ExistingPeriodicWorkPolicy.KEEP,p); PeriodicWorkRequest n=new PeriodicWorkRequest.Builder(NotificationPollWorker.class,15,TimeUnit.MINUTES).setConstraints(net).build(); WorkManager.getInstance(c).enqueueUniquePeriodicWork("poll_notificaciones",ExistingPeriodicWorkPolicy.KEEP,n);} public static void sincronizarAhora(Context c){Constraints net=new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build();OneTimeWorkRequest r=new OneTimeWorkRequest.Builder(SincronizarPendientesWorker.class).setConstraints(net).build();WorkManager.getInstance(c).enqueueUniqueWork("sync_incidentes_ahora",ExistingWorkPolicy.REPLACE,r);} }
